def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n == 3:
        return 'C'
    if n == 4:
        opp_def = 0
        for a, b in history:
            if b == 'D':
                opp_def += 1
        if opp_def >= 4:
            return 'D'
        return 'C'
    if n == 5:
        opp_def = 0
        for a, b in history:
            if b == 'D':
                opp_def += 1
        if opp_def >= 4:
            return 'D'
        return 'C'
    if n == 6:
        opp_def = 0
        for a, b in history:
            if b == 'D':
                opp_def += 1
        if opp_def >= 5:
            return 'D'
        return 'C'
    if n == 7:
        opp_def = 0
        for a, b in history:
            if b == 'D':
                opp_def += 1
        if opp_def >= 5:
            return 'D'
        return 'C'
    if n == 8:
        opp_def = 0
        for a, b in history:
            if b == 'D':
                opp_def += 1
        if opp_def >= 5:
            return 'D'
        return 'C'
    if n == 9:
        opp_def = 0
        for a, b in history:
            if b == 'D':
                opp_def += 1
        if opp_def >= 5:
            return 'D'
        return 'C'

    opp_def_total = 0
    for a, b in history:
        if b == 'D':
            opp_def_total += 1

    recent = history[-8:]
    recent_opp_def = 0
    recent_both_def = 0
    for a, b in recent:
        if b == 'D':
            recent_opp_def += 1
        if b == 'D' and a == 'D':
            recent_both_def += 1

    last_my = history[-1][0]
    last_opp = history[-1][1]

    consecutive_opp_def = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consecutive_opp_def += 1
        else:
            break

    consecutive_opp_coop = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            consecutive_opp_coop += 1
        else:
            break

    consecutive_both_def = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            consecutive_both_def += 1
        else:
            break

    if n >= 12 and opp_def_total == 0:
        if n >= 96:
            return 'D'
        if n >= 85:
            return 'D'
        if n % 11 == 0 and n >= 30:
            return 'D'
        return 'C'

    if opp_def_total >= n - 1 and n >= 10:
        if n % 13 == 0:
            return 'C'
        return 'D'

    if recent_opp_def >= 7:
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    remaining = 100 - n

    if remaining <= 1:
        if opp_def_total == 0:
            return 'D'
        if consecutive_opp_coop >= 3:
            return 'D'
        return 'D'

    if remaining <= 3:
        if consecutive_opp_coop >= 2:
            return 'D'
        if opp_def_total * 10 <= n * 2:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if consecutive_opp_def >= 6:
        return 'D'

    if consecutive_both_def >= 3:
        if rng.random() < 0.55:
            return 'C'
        return 'D'

    if last_opp == 'D':
        if consecutive_opp_def == 1:
            if opp_def_total * 5 <= n and n >= 15:
                if rng.random() < 0.85:
                    return 'C'
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        if consecutive_opp_def == 2:
            if opp_def_total * 5 <= n * 2 and n >= 15:
                if rng.random() < 0.6:
                    return 'C'
            return 'D'
        if consecutive_opp_def == 3:
            if opp_def_total * 2 <= n and n >= 20:
                if rng.random() < 0.4:
                    return 'C'
            return 'D'
        return 'D'

    if consecutive_opp_coop >= 7:
        if n >= 25 and remaining > 10:
            if n % 13 == 0:
                return 'D'
        return 'C'

    if last_my == 'D' and last_opp == 'C':
        if n >= 20 and remaining > 5:
            if opp_def_total * 4 <= n:
                return 'D'
        return 'C'

    return 'C'
